-- All fixtures and permission changes roll back. No production content is changed.
BEGIN;
DO $$
DECLARE cid uuid; uid uuid; othercid uuid; pid uuid; otherpid uuid; ts timestamptz; stale timestamptz; saved jsonb; rejected boolean; f1 uuid; f2 uuid; rev integer;
BEGIN
 SELECT id,user_id INTO cid,uid FROM public.clients WHERE user_id IS NOT NULL AND status='active' AND NOT churned LIMIT 1;
 SELECT id INTO othercid FROM public.clients WHERE id<>cid LIMIT 1;
 IF cid IS NULL OR othercid IS NULL THEN RAISE EXCEPTION 'Two existing accounts required';END IF;
 PERFORM set_config('request.jwt.claim.sub','957e2e55-69ed-4e12-bcc0-529ea83380a5',true);
 UPDATE public.client_portal_settings SET can_view_posts=true,can_view_history=true,can_view_media=true,can_approve=true,can_view_captions=true,visible_statuses=ARRAY['review','changes_requested','approved','scheduled','published'] WHERE client_id=cid;
 INSERT INTO public.posts(client_id,title,caption,status,scheduled_date,scheduled_time) VALUES(cid,'QA calendar','Original','review',current_date+10,'14:35') RETURNING id,updated_at INTO pid,ts;
 INSERT INTO public.posts(client_id,title,status,scheduled_date) VALUES(othercid,'QA isolated calendar','review',current_date+10) RETURNING id INTO otherpid;
 SET LOCAL ROLE authenticated;
 IF NOT public.can_edit_calendar() THEN RAISE EXCEPTION 'Admin edit denied';END IF;
 stale:=ts;
 saved:=public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date+11));ts:=(saved->>'updated_at')::timestamptz;
 IF saved->>'scheduled_time'<>'14:35:00' OR saved->>'scheduled_date'<>(current_date+11)::text THEN RAISE EXCEPTION 'Monthly move changed time';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.post_schedule_events WHERE post_id=pid AND actor_id=auth.uid() AND previous_date=current_date+10 AND new_date=current_date+11 AND timezone=public.calendar_timezone()) THEN RAISE EXCEPTION 'Missing trusted audit';END IF;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,stale,'{"title":"stale overwrite"}');EXCEPTION WHEN serialization_failure THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Stale write accepted';END IF;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,jsonb_build_object('client_id',othercid));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Editor account changed';END IF;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date-2));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Past date accepted';END IF;
 saved:=public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date+10));ts:=(saved->>'updated_at')::timestamptz;
 IF (SELECT count(*) FROM public.posts WHERE id=pid)<>1 OR NOT EXISTS(SELECT 1 FROM public.posts WHERE id=pid AND scheduled_date=current_date+10) THEN RAISE EXCEPTION 'Undo did not restore same post';END IF;
 UPDATE public.posts SET status='published' WHERE id=pid RETURNING updated_at INTO ts;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date+12));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Published move allowed';END IF;
 UPDATE public.posts SET status='review',publication_source='external-test' WHERE id=pid RETURNING updated_at INTO ts;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date+12));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'External schedule reported success';END IF;
 UPDATE public.posts SET publication_source=NULL WHERE id=pid RETURNING updated_at INTO ts;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',uid::text,true);SET LOCAL ROLE authenticated;
 IF public.can_edit_calendar() THEN RAISE EXCEPTION 'Client gained edit';END IF;
 IF EXISTS(SELECT 1 FROM public.portal_posts WHERE id=otherpid) OR EXISTS(SELECT 1 FROM public.posts WHERE id=pid) THEN RAISE EXCEPTION 'Account isolation failed';END IF;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,'{"title":"forbidden"}');EXCEPTION WHEN insufficient_privilege THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Client RPC write allowed';END IF;
 UPDATE public.posts SET title='forbidden direct' WHERE id=pid;IF FOUND THEN RAISE EXCEPTION 'Client direct write';END IF;
 PERFORM public.decide_my_account_post(pid,ts,'approved',NULL);
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','957e2e55-69ed-4e12-bcc0-529ea83380a5',true);SET LOCAL ROLE authenticated;
 SELECT updated_at INTO ts FROM public.posts WHERE id=pid;
 saved:=public.save_calendar_post(pid,ts,jsonb_build_object('scheduled_date',current_date+13));ts:=(saved->>'updated_at')::timestamptz;
 IF saved->>'status'<>'review' OR NOT EXISTS(SELECT 1 FROM public.post_approvals WHERE post_id=pid AND decision='pending') THEN RAISE EXCEPTION 'Date retained approval';END IF;
 INSERT INTO public.post_files(post_id,file_name,storage_path,mime_type) VALUES(pid,'a.png',pid||'/a.png','image/png') RETURNING id INTO f1;
 INSERT INTO public.post_files(post_id,file_name,storage_path,mime_type) VALUES(pid,'b.png',pid||'/b.png','image/png') RETURNING id INTO f2;
 SELECT updated_at,content_revision INTO ts,rev FROM public.posts WHERE id=pid;
 saved:=public.change_calendar_media(pid,ts,'order',jsonb_build_object('ids',jsonb_build_array(f2,f1)));ts:=(saved->>'updated_at')::timestamptz;
 IF NOT EXISTS(SELECT 1 FROM public.post_files WHERE id=f2 AND sort_order=1) OR (saved->>'content_revision')::int<=rev THEN RAISE EXCEPTION 'Media order/revision failed';END IF;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',uid::text,true);SET LOCAL ROLE authenticated;
 PERFORM public.decide_my_account_post(pid,ts,'approved',NULL);
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','957e2e55-69ed-4e12-bcc0-529ea83380a5',true);SET LOCAL ROLE authenticated;
 SELECT updated_at INTO ts FROM public.posts WHERE id=pid;
 IF NOT EXISTS(SELECT 1 FROM public.post_review_events WHERE post_id=pid AND snapshot->'files'->0->>'file_name'='b.png' AND snapshot->>'time'='14:35:00') THEN RAISE EXCEPTION 'Approval snapshot lost media order/time';END IF;
 rejected:=false;BEGIN PERFORM public.change_calendar_media(pid,ts,'order',jsonb_build_object('ids',jsonb_build_array(f1,f1)));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Invalid media list accepted';END IF;
 rejected:=false;BEGIN PERFORM public.change_calendar_media(pid,ts,'attach',jsonb_build_object('storage_path',otherpid||'/fake.png','file_name','fake.png'));EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Foreign upload accepted';END IF;
 saved:=public.change_calendar_media(pid,ts,'remove',jsonb_build_object('id',f1));ts:=(saved->>'updated_at')::timestamptz;
 IF EXISTS(SELECT 1 FROM public.post_files WHERE id=f1) THEN RAISE EXCEPTION 'Media removal failed';END IF;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','2b31ad51-1a75-448f-aa2b-0ef935d127b9',true);SET LOCAL ROLE authenticated;
 IF NOT public.can_edit_calendar() THEN RAISE EXCEPTION 'Authorized team edit denied';END IF;
 saved:=public.save_calendar_post(pid,ts,'{"caption":"Team caption"}');ts:=(saved->>'updated_at')::timestamptz;
 RESET ROLE;
 DELETE FROM public.module_visibility WHERE scope='user' AND scope_id='2b31ad51-1a75-448f-aa2b-0ef935d127b9' AND module_key='social.calendar';
 INSERT INTO public.module_visibility(scope,scope_id,module_key,visible)VALUES('user','2b31ad51-1a75-448f-aa2b-0ef935d127b9','social.calendar',false);
 SET LOCAL ROLE authenticated;
 IF public.can_edit_calendar() THEN RAISE EXCEPTION 'Visibility override ignored';END IF;
 UPDATE public.posts SET title='Forbidden team write' WHERE id=pid;IF FOUND THEN RAISE EXCEPTION 'Team direct permission bypass';END IF;
 rejected:=false;BEGIN PERFORM public.save_calendar_post(pid,ts,'{"title":"Forbidden team RPC"}');EXCEPTION WHEN insufficient_privilege THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Team RPC permission bypass';END IF;
 rejected:=false;BEGIN INSERT INTO public.post_files(post_id,file_name,storage_path)VALUES(pid,'forbidden.png',pid||'/forbidden.png');EXCEPTION WHEN insufficient_privilege THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'Team media permission bypass';END IF;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','957e2e55-69ed-4e12-bcc0-529ea83380a5',true);SET LOCAL ROLE authenticated;
 INSERT INTO public.navigation_preferences(user_id,calendar_density,calendar_filters_open) VALUES(auth.uid(),'compact',false) ON CONFLICT(user_id) DO UPDATE SET calendar_density='compact',calendar_filters_open=false;
 IF NOT EXISTS(SELECT 1 FROM public.navigation_preferences WHERE user_id=auth.uid() AND calendar_density='compact' AND NOT calendar_filters_open) THEN RAISE EXCEPTION 'Preference persistence failed';END IF;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',uid::text,true);SET LOCAL ROLE authenticated;
 IF EXISTS(SELECT 1 FROM public.navigation_preferences WHERE user_id<>auth.uid()) THEN RAISE EXCEPTION 'Foreign preference leak';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.portal_posts WHERE id=pid AND scheduled_date=current_date+13 AND status='review') THEN RAISE EXCEPTION 'Portal date/status not synchronized';END IF;
 IF EXISTS(SELECT 1 FROM public.post_schedule_events WHERE post_id=otherpid) THEN RAISE EXCEPTION 'Foreign history leak';END IF;
 RESET ROLE;
END $$;
ROLLBACK;
SELECT 'PASS: real role/RLS, same-record move and undo, preserved time, audit, stale conflict, published/past/external rejection, account isolation, approval reset, media order/ownership, preferences, portal synchronization' result;
